# -*- coding: utf-8 -*-
"""Simulacro final 4TC-17 · preguntas 26 a 50."""

P2 = [
 dict(nivel='intermediate', tema='Supervisión del territorio',
  ctx='Una Procuraduría Provincial tiene dudas sobre cómo tramitar la licencia no remunerada de un servidor de su sede y consulta a la División de Gestión Humana. En la dependencia hay dos lecturas: un servidor sostiene que, al consultar, la Provincial pierde el asunto y la División debe tramitar directamente todas las novedades de esa sede; otro cree que la División debe negarse a responder, porque la administración del personal territorial no es asunto suyo y responder sentaría un precedente.',
  q='¿Cuál es la lectura correcta del papel de la División en ese escenario?',
  ops=['La Provincial pierde la gestión al consultar: desde ese momento la División asume la administración del personal de esa sede, tramita sus novedades y responde por ellas ante la Secretaría General.',
       'La División supervisa la administración de gestión humana en los niveles territoriales: fija el criterio y resuelve la consulta, y la operación del trámite sigue a cargo de la Provincial.',
       'La División debe negarse, porque sus funciones se agotan en el personal del nivel central y orientar a una sede territorial sobre un trámite de personal excede lo que le asigna la norma.',
       'La División debe remitir la consulta a la Procuraduría Auxiliar para Asuntos Disciplinarios, que es la dependencia encargada de coordinar los asuntos que involucran a varias áreas.'],
  correcta=1,
  expl=['Incorrecto: supervisar no es absorber la operación.',
        'Correcto: el numeral 11 del artículo 63 le encarga supervisar la gestión humana en los niveles territoriales.',
        'Incorrecto: supervisar incluye resolver la consulta.',
        'Incorrecto: la Procuraduría Auxiliar no es una instancia de talento humano.'],
  ref='Decreto Ley 262 de 2000, art. 63 núm. 11', refT='Supervisión de la gestión humana territorial'),

 dict(nivel='basic', tema='Servidor público y contratista',
  ctx='En una reunión del equipo de la División, una compañera sostiene que a un contratista de prestación de servicios que apoya el área hace un año se le debe tramitar la evaluación del desempeño, reconocerle vacaciones remuneradas y computarle ese tiempo para carrera, «porque trabaja aquí todos los días igual que nosotros». El jefe le pide a usted precisar el punto antes de que el equipo tramite algo, porque de ello depende qué documentos se le abren en el sistema de personal.',
  q='¿Qué es lo correcto según la naturaleza del vínculo?',
  ops=['La compañera tiene razón: quien presta servicios de forma permanente adquiere de hecho la condición de servidor público y, con ella, evaluación, vacaciones remuneradas y tiempo para carrera.',
       'El contratista no es servidor público ni ocupa un empleo de la planta: su vínculo se rige por la contratación estatal, de modo que no le corresponden carrera, situaciones administrativas ni evaluación.',
       'El contratista es un servidor público de régimen especial, de manera que le corresponden la evaluación y el cómputo del tiempo para carrera, pero no las vacaciones remuneradas de la planta.',
       'El contratista no es servidor público, pero superado el año de vinculación continua la entidad debe incorporarlo a la planta temporal y reconocerle desde entonces las garantías del empleo público.'],
  correcta=1,
  expl=['Incorrecto: la permanencia de hecho no crea derechos de carrera; esa es la situación irregular del contrato realidad.',
        'Correcto: el vínculo contractual no es legal y reglamentario, y se rige por el estatuto de contratación.',
        'Incorrecto: no existe esa categoría intermedia.',
        'Incorrecto: no hay incorporación automática a la planta temporal por cumplir un año.'],
  ref='Ley 80 de 1993, art. 32 núm. 3; Ley 909 de 2004', refT='Servidor público frente a contratista'),

 dict(nivel='advanced', tema='Motivación del acto',
  ctx='Al revisar un proyecto de acto que niega una solicitud, usted encuentra que la parte motiva transcribe cuatro artículos completos del CPACA y del Decreto 1083, seguidos de la frase «en consecuencia, se niega lo solicitado». No hay un solo párrafo que explique qué hechos se probaron ni por qué esas normas conducen a negar. El compañero que lo proyectó dice que «citando la norma ya está motivado» y que agregar explicaciones solo le daría argumentos al interesado, que ya anunció que recurrirá.',
  q='¿Cuál es la observación correcta?',
  ops=['Transcribir normas no es motivar: el acto debe exponer qué hechos se probaron, con qué soportes, y por qué esas normas aplicadas a esos hechos conducen a la decisión que se adopta.',
       'El proyecto está bien motivado porque identifica con precisión el fundamento normativo, que es lo que exige la ley, y añadir razones adicionales expondría innecesariamente a la entidad.',
       'Basta con reducir las transcripciones a los apartes pertinentes de cada artículo, porque el exceso de citas dificulta la lectura pero no afecta la validez de la motivación del acto.',
       'La motivación solo es exigible cuando el acto es favorable al interesado, de modo que en una negativa basta con invocar la norma que sustenta la decisión que se está adoptando.'],
  correcta=0,
  expl=['Correcto: motivar es permitir reconstruir el razonamiento; sin eso el interesado no puede controvertir.',
        'Incorrecto: identificar la norma es necesario pero no suficiente.',
        'Incorrecto: recortar citas mejora la lectura pero no agrega razonamiento.',
        'Incorrecto: es al revés; la motivación es especialmente exigible en las decisiones desfavorables.'],
  ref='Ley 1437 de 2011, art. 42', refT='Deber de motivación'),

 dict(nivel='intermediate', tema='Recursos contra el acto',
  ctx='Un servidor recibe su calificación anual, no está de acuerdo y se acerca a su puesto. Pregunta si puede hacer algo, en qué término y ante quién. Un compañero le dice que «contra eso no hay recurso porque es una valoración del jefe» y otro, que «puede ir directamente a demandar». El servidor pide una respuesta clara porque dice que ya perdió dos días averiguando y no quiere que se le venza nada. Usted tiene a la vista el acto de calificación y la constancia de su notificación.',
  q='¿Cuál es la orientación correcta?',
  ops=['No procede recurso alguno porque la calificación es una valoración subjetiva del evaluador, de modo que la única vía del servidor es acudir ante la jurisdicción de lo contencioso administrativo.',
       'Puede presentar su inconformidad en cualquier momento mientras permanezca en el empleo, porque la calificación no adquiere firmeza y puede revisarse cada vez que el servidor lo solicite.',
       'Debe esperar a la siguiente calificación y pedir allí que se compensen los puntos, porque las calificaciones se revisan de manera acumulada al cierre de cada ciclo de evaluación anual.',
       'La calificación es un acto administrativo que se notifica y contra el cual proceden recursos: debe orientarlo sobre cuál procede, el término y ante quién, y dejar constancia de la orientación.'],
  correcta=3,
  expl=['Incorrecto: decir que no hay recurso le cierra la vía interna.',
        'Incorrecto: la calificación sí adquiere firmeza.',
        'Incorrecto: no existe compensación de puntos entre ciclos.',
        'Correcto: la calificación es un acto administrativo; se notifica, admite recursos y adquiere firmeza, y además debe ser motivada.'],
  ref='Decreto Ley 262 de 2000, art. 226; Ley 1437 de 2011, art. 74', refT='Recursos contra la calificación'),

 dict(nivel='intermediate', tema='Impedimentos',
  ctx='Llega a su puesto una petición en la que una persona pide que se revise la liquidación de una prestación. Al abrirla usted advierte que la peticionaria es su hermana, con quien no tiene ningún conflicto y a quien no ve hace meses. El grupo está corto de personal, el término ya está corriendo y nadie en la División conoce el parentesco. Usted está seguro de poder tramitar el asunto con total objetividad y, además, es quien más rápido lo resolvería.',
  q='¿Cuál es la actuación correcta?',
  ops=['Tramitar la petición con normalidad y dejar al final una constancia en el expediente que advierta el parentesco, de modo que quien revise el trámite pueda valorarlo si lo considera.',
       'Manifestar el impedimento por escrito ante el competente antes de intervenir, describiendo el parentesco, y dejar constancia: quien decide dispondrá quién continúa con el trámite.',
       'Tramitarla porque el impedimento solo opera cuando quien decide es el pariente, y usted no decide nada: se limita a verificar soportes y a proyectar la respuesta que otro firmará.',
       'Pedirle a un compañero que firme el proyecto en su lugar, conservando usted la elaboración del documento, de modo que el trámite avance sin que su nombre aparezca en la actuación.'],
  correcta=1,
  expl=['Incorrecto: la constancia al final invierte el orden; la decisión sobre su participación debe tomarse antes.',
        'Correcto: el impedimento se manifiesta por escrito y antes de intervenir, y lo resuelve el competente.',
        'Incorrecto: quien prepara la actuación influye en ella.',
        'Incorrecto: repartir la firma es ocultar el vínculo.'],
  ref='Ley 1437 de 2011, arts. 11 y 12', refT='Impedimentos y recusaciones'),

 dict(nivel='basic', tema='Habeas data',
  ctx='Una servidora pide que se corrija un dato de su historia laboral que, según ella, está equivocado y le está afectando una certificación ya expedida. Un compañero le dice a usted que la historia laboral es un documento de la entidad y que «el servidor no puede andar pidiendo que le cambien lo que dice». Otro propone corregirlo de inmediato sin verificar nada, porque es ella quien mejor conoce sus propios datos personales y laborales.',
  q='¿Cuál es la orientación correcta?',
  ops=['El habeas data le da derecho a conocer, actualizar y rectificar los datos que sobre ella reposen: debe radicarse su solicitud, verificarse contra los soportes y responderse de fondo y motivadamente.',
       'La servidora no tiene derecho a pedir modificaciones a la historia laboral porque es un documento de la entidad, y lo único que puede hacer es solicitar copia de lo que allí reposa.',
       'Debe corregirse de inmediato el dato que ella señala, porque el titular del dato es quien tiene la información correcta y la entidad debe atender su manifestación sin más trámite.',
       'Debe remitirse la solicitud a la oficina jurídica para que determine si procede, porque modificar un documento ya archivado exige un concepto previo sobre la viabilidad del cambio.'],
  correcta=0,
  expl=['Correcto: el art. 15 reconoce el derecho a conocer, actualizar y rectificar; se radica, se verifica y se responde de fondo.',
        'Incorrecto: negar el derecho desconoce la Constitución.',
        'Incorrecto: corregir sin verificar es el extremo contrario; el dato soporta liquidaciones y certificaciones.',
        'Incorrecto: no hace falta un concepto previo para tramitar lo que la Constitución reconoce.'],
  ref='Constitución Política, art. 15; Ley 1581 de 2012', refT='Habeas data'),

 dict(nivel='advanced', tema='Empleo temporal y mérito',
  ctx='La entidad tiene una necesidad permanente de personal por el crecimiento sostenido de la operación. Para cubrirla rápido, un directivo propone crear un «empleo temporal» y nombrar en él, sin concurso, a una persona de su confianza. Le dice que es una figura legal, prevista en la ley, y que al ser temporal «no afecta el mérito de nadie». Le pide a usted que proyecte lo necesario para esta semana y advierte que el retraso quedará a nombre de la División.',
  q='¿Cómo debe actuar?',
  ops=['Proyectar la creación del empleo temporal y el nombramiento como pide el directivo, porque la figura está prevista en la ley, permite vincular con agilidad y su carácter temporal no afecta el mérito.',
       'Proyectar solo el nombramiento en el empleo temporal, sin crear formalmente el cargo ni motivarlo, porque lo urgente es cubrir la necesidad y la formalización puede completarse después.',
       'Explicarle que el empleo temporal es excepcional, solo procede para funciones no permanentes y exige motivación técnica y respaldo presupuestal, de modo que usarlo así es un fraude al mérito.',
       'Proyectar la creación del empleo temporal pero exigir que la persona se seleccione de la lista de elegibles vigente más próxima, de modo que la figura quede saneada por el mérito.'],
  correcta=2,
  expl=['Incorrecto: el rótulo «temporal» no sanea el fraude al mérito.',
        'Incorrecto: nombrar sin crear ni motivar el cargo agrava el vicio.',
        'Correcto: el empleo temporal es para funciones no permanentes, con motivación técnica, planta de temporales y presupuesto.',
        'Incorrecto: tomar a alguien de una lista de elegibles para un empleo distinto es otra irregularidad.'],
  ref='Ley 909 de 2004, art. 21', refT='Empleos temporales'),

 dict(nivel='intermediate', tema='Uso del sistema de información',
  ctx='Un viernes al final de la tarde, un servidor de otra dependencia se acerca a su puesto y le pide que use su acceso al sistema de personal para consultar si un compañero de otra sede tiene una sanción disciplinaria anotada en su historia laboral. Dice que es para saber «con quién se va a trabajar» en un equipo nuevo y que no necesita documentos, solo que le confirme sí o no. Insiste en que nadie se va a enterar. El sistema registra cada consulta con el usuario que la hace.',
  q='¿Cuál es la actuación correcta?',
  ops=['Confirmarle solo si existe o no la anotación, sin dar detalles ni entregar documentos, porque un sí o un no no constituye entrega de información y evita un problema en el equipo nuevo.',
       'Consultar el sistema y, si efectivamente hay una sanción, informarlo al jefe de la dependencia que está armando el equipo, porque esa información es relevante para conformar el grupo.',
       'Negarse a consultar pero sugerirle que le pida directamente al compañero su certificado de antecedentes, de modo que sea él quien decida si comparte esa información con el equipo.',
       'No usar el acceso para un fin ajeno a su función, explicarle que la información de la historia laboral está protegida y que existe un canal formal, y dejar constancia de la solicitud.'],
  correcta=3,
  expl=['Incorrecto: un «sí o no» es entregar exactamente la información pedida.',
        'Incorrecto: convertirse en informante ante quien nada ha pedido por el canal agrava el asunto.',
        'Incorrecto: trasladar la presión al compañero afectado no resuelve nada.',
        'Correcto: el acceso se tiene por razón de las funciones y para ellas; se explica el límite y se deja constancia.'],
  ref='Ley 1581 de 2012; Ley 1952 de 2019, deberes del servidor', refT='Uso del acceso a los sistemas'),

 dict(nivel='advanced', tema='Liquidación y fecha de retiro',
  ctx='Un servidor se retira con efectos del día 18 del mes. El jefe de su dependencia le pide a usted que proyecte la liquidación definitiva «como si saliera el 30, que es más fácil de calcular y de todos modos son unos días». El servidor, por su parte, pregunta si le pagarán el mes completo y si eso cambia su liquidación de vacaciones. Usted tiene a la vista el acto de retiro firmado, con su fecha, y la hoja de tiempo de servicio del expediente.',
  q='¿Cómo debe proyectarse la liquidación?',
  ops=['Con la fecha real de retiro que fija el acto, el día 18, liquidando hasta ese día los conceptos que correspondan, y explicar al servidor cómo se calculó cada uno de ellos.',
       'Con la fecha del día 30, como pide el jefe, porque la diferencia es de pocos días y simplifica un cálculo que de otro modo exigiría prorratear varios conceptos del período liquidado.',
       'Con la fecha del día 18 para el salario pero con el mes completo para las prestaciones, porque estas se causan por períodos mensuales y no admiten liquidación por fracción de mes.',
       'Con la fecha que el servidor prefiera entre las dos, siempre que lo manifieste por escrito, porque es una diferencia menor que no afecta derechos de terceros ni recursos públicos.'],
  correcta=0,
  expl=['Correcto: la fecha la fija el acto administrativo, no la conveniencia del cálculo; y explicar el cálculo evita la reclamación posterior.',
        'Incorrecto: pagaría doce días no trabajados con recursos públicos.',
        'Incorrecto: las prestaciones también se liquidan por el tiempo efectivamente servido.',
        'Incorrecto: la fecha de retiro no se negocia con el interesado.'],
  ref='Decreto 1083 de 2015', refT='Liquidación definitiva'),

 dict(nivel='basic', tema='Inducción y reinducción',
  ctx='Entran cinco servidores nuevos el lunes y, además, un grupo de servidores antiguos cambió de funciones tras una reorganización. Un compañero le comenta que «eso se resuelve con un correo de bienvenida y el enlace al reglamento» y que la reinducción «no existe, eso es solo para los que entran». Usted debe proponer al jefe cómo se atenderá a los dos grupos, y tiene a la vista el programa institucional y los registros de asistencia de los últimos ciclos.',
  q='¿Cuál es el planteamiento correcto?',
  ops=['El compañero tiene razón: la inducción se agota con la entrega de información institucional y la reinducción no está prevista, de modo que basta un correo para quienes ingresan.',
       'Debe programarse inducción para quienes ingresan y reinducción para quienes ya están pero enfrentan cambios de funciones, normas o estructura, porque la División contribuye a ambos programas.',
       'Debe programarse inducción para los dos grupos por igual, porque quien cambia de funciones ingresa materialmente a un nuevo empleo y le corresponde el mismo proceso que a quien llega.',
       'No corresponde a la División programar nada: la inducción y la reinducción son responsabilidad del jefe inmediato de cada servidor, que es quien conoce las funciones del puesto.'],
  correcta=1,
  expl=['Incorrecto: la reinducción sí existe y la inducción no se agota en un correo.',
        'Correcto: el numeral 2 del artículo 63 encarga a la División contribuir al diseño y aplicación de ambos programas.',
        'Incorrecto: son programas distintos con finalidades distintas.',
        'Incorrecto: el jefe aporta lo propio del puesto, pero el programa lo diseña y aplica el área.'],
  ref='Decreto Ley 262 de 2000, art. 63 núm. 2', refT='Inducción y reinducción'),

 dict(nivel='intermediate', tema='Requisitos para el ascenso',
  ctx='Un servidor le pregunta si una sanción disciplinaria que le impusieron hace tres años le impide participar en el concurso de ascenso que la entidad acaba de convocar. Un compañero le dice que «cualquier sanción inhabilita de por vida para ascender» y otro, que «las sanciones no tienen nada que ver con los concursos internos». El servidor necesita decidir si se inscribe, el plazo cierra esta semana y usted tiene acceso a los registros que permiten verificar la fecha exacta.',
  q='¿Cuál es la orientación correcta?',
  ops=['Que cualquier sanción disciplinaria inhabilita de manera permanente para participar en concursos de ascenso, de modo que no tiene sentido que se inscriba en el proceso convocado.',
       'Que las sanciones disciplinarias no tienen incidencia alguna en los concursos internos, de modo que puede inscribirse sin verificar nada sobre su situación disciplinaria anterior.',
       'Que debe consultar directamente con la oficina de control interno disciplinario, porque la División no tiene competencia para pronunciarse sobre los efectos de una sanción en un concurso.',
       'Que el artículo 193 exige, para el ascenso, no haber sido sancionado el año anterior, además de calificación y reinducción iguales o superiores al 70 %, y verificar la fecha exacta.'],
  correcta=3,
  expl=['Incorrecto: no inhabilita de por vida; la norma fija una ventana temporal.',
        'Incorrecto: sí tienen incidencia, dentro de esa ventana.',
        'Incorrecto: la División administra la información de carrera y apoya a la Comisión de Carrera.',
        'Correcto: el art. 193 del Decreto Ley 262 exige calificación ≥ 70 %, no haber sido sancionado el año anterior y ≥ 70 % en reinducción.'],
  ref='Decreto Ley 262 de 2000, art. 193', refT='Requisitos del concurso de ascenso'),

 dict(nivel='advanced', tema='Verificación documental',
  ctx='Verificando los requisitos de una persona nombrada, usted advierte que en la certificación de estudios la fecha de expedición aparece en una tipografía distinta del resto del documento y que el número de registro no sigue el formato que usa esa institución en los demás certificados que reposan en la División. Un compañero le dice que escriba en la constancia que «el documento es falso» y otro, que no mencione nada porque «no es perito». La posesión está programada para pasado mañana.',
  q='¿Cuál es la actuación correcta?',
  ops=['Consignar en la constancia que el documento es falso y poner los hechos en conocimiento del competente, para que compulse copias a la Fiscalía antes de que la posesión se surta.',
       'Describir con precisión los elementos observados, consignar que el requisito no queda acreditado con ese soporte y poner el hecho en conocimiento del competente, sin calificar el documento.',
       'No mencionar la irregularidad y limitarse a consignar que el documento fue aportado, porque establecer la autenticidad de un certificado excede la competencia técnica de la División.',
       'Llamar a la institución educativa para confirmar verbalmente si el certificado es auténtico y, según lo que respondan, decidir si se consigna o no la observación en la constancia.'],
  correcta=1,
  expl=['Incorrecto: declarar la falsedad es calificar, y exige peritaje y decisión de otro.',
        'Correcto: la función 2 permite examinar la idoneidad del método y describir lo observado; concluir que el requisito no queda acreditado sí corresponde.',
        'Incorrecto: callar compromete la veracidad de la constancia.',
        'Incorrecto: una confirmación telefónica informal no deja soporte ni sustituye el requerimiento formal.'],
  ref='Manual de funciones, función 2', refT='Examen de pertinencia e idoneidad'),

 dict(nivel='intermediate', tema='Comisión de Personal',
  ctx='Una vacante temporal de un empleo de carrera se proveyó por encargo. Una empleada de carrera que creía tener mejor derecho por cumplir los requisitos y tener calificación sobresaliente considera que el encargo se otorgó mal y anuncia que acudirá a la Comisión de Personal. Llega a su puesto con el escrito en la mano y le pide que usted «le diga de una vez si tiene razón o no», porque no quiere perder tiempo si el reclamo no procede.',
  q='¿Cuál es la actuación correcta?',
  ops=['Radicar el escrito y encauzarlo hacia la Comisión de Personal, que vela por que las actuaciones de personal se ajusten a las normas de carrera, informar al jefe y dejar constancia, sin pronunciarse.',
       'Responderle usted mismo que el encargo ya está decidido y que no hay nada que revisar, porque una vez otorgado un encargo la decisión es definitiva e inmodificable para la entidad.',
       'Modificar el encargo a favor de ella de inmediato, porque si cumple los requisitos y tiene calificación sobresaliente es evidente que tenía mejor derecho y corregirlo reduce el perjuicio.',
       'Revisar con ella los soportes del encargo y darle su opinión técnica sobre si el reclamo prospera, para que decida con información si vale la pena presentarlo ante la Comisión.'],
  correcta=0,
  expl=['Correcto: la Comisión de Personal es el órgano interno competente; el papel del técnico es radicar, encauzar, informar y dejar constancia.',
        'Incorrecto: cerrarle la puerta desconoce la instancia que existe para eso.',
        'Incorrecto: modificar el encargo excede por completo su competencia.',
        'Incorrecto: anticipar una opinión compromete su imparcialidad y puede inducirla a desistir.'],
  ref='Ley 909 de 2004, art. 16; Decreto Ley 262 de 2000, art. 63 núm. 13', refT='Comisión de Personal'),

 dict(nivel='advanced', tema='Silencio administrativo',
  ctx='Una petición en interés particular fue radicada hace más de tres meses y la entidad no la ha respondido. El peticionario llega preguntando qué pasó y qué puede hacer de aquí en adelante. Un compañero le dice que «como no hubo respuesta, se entiende aceptada su solicitud» y otro, que «ya no hay nada que hacer porque el plazo venció». El peticionario quiere saber exactamente cuál es su situación y si todavía puede obtener una respuesta.',
  q='¿Qué debe explicarle?',
  ops=['Que al vencer el plazo sin respuesta operó un silencio positivo y que, en consecuencia, su solicitud se entiende concedida y puede exigir su cumplimiento ante la propia entidad.',
       'Que la regla general es el silencio administrativo negativo —la petición se entiende negada— y que eso le permite acudir a los medios de control, sin que la entidad quede relevada de responder.',
       'Que el vencimiento del plazo extingue su derecho a obtener una respuesta, de modo que su única alternativa es presentar una nueva petición para que el término comience otra vez.',
       'Que el silencio no produce ningún efecto mientras la entidad no expida un acto que lo declare, de modo que debe esperar a que la administración se pronuncie formalmente al respecto.'],
  correcta=1,
  expl=['Incorrecto: el silencio positivo es excepcional y solo opera donde una norma expresa lo prevé.',
        'Correcto: la regla general es el silencio negativo, y la entidad conserva el deber de responder.',
        'Incorrecto: el vencimiento no extingue el derecho a la respuesta.',
        'Incorrecto: el silencio opera por ministerio de la ley.'],
  ref='Ley 1437 de 2011, arts. 83 y 84', refT='Silencio administrativo'),

 dict(nivel='intermediate', tema='Jerarquía de controles en SST',
  ctx='Se identificó un riesgo por exposición a ruido en un área de la entidad. Un compañero propone resolverlo entregando protectores auditivos a todos los servidores de esa área y dejar constancia firmada de la entrega; otro propone poner un aviso que recuerde su uso. Usted sabe que el ruido proviene de un equipo específico que podría reubicarse o encerrarse, y que la entrega de protectores ya se hizo el año pasado sin que el ruido disminuyera en el área.',
  q='¿Cuál es el enfoque correcto?',
  ops=['Aplicar la jerarquía de controles: evaluar primero eliminar o sustituir la fuente, luego los controles de ingeniería y administrativos, y dejar los elementos de protección personal como última medida.',
       'Entregar los protectores auditivos con constancia firmada, porque es la medida más rápida, de menor costo y que traslada al servidor la responsabilidad de protegerse durante su jornada.',
       'Instalar avisos de uso obligatorio en el área, porque la señalización es el control administrativo más eficaz y asegura que el servidor recuerde la medida en el momento de la exposición.',
       'Solicitar a la ARL que califique el riesgo y esperar su concepto antes de adoptar cualquier medida, de modo que la decisión quede respaldada técnicamente por la administradora de riesgos.'],
  correcta=0,
  expl=['Correcto: eliminar, sustituir, controles de ingeniería, administrativos y, al final, el EPP.',
        'Incorrecto: empezar por el EPP invierte la jerarquía y ya se probó sin resultado.',
        'Incorrecto: un aviso no reduce el ruido.',
        'Incorrecto: la asesoría de la ARL no exime de la obligación de controlar.'],
  ref='Decreto 1072 de 2015, art. 2.2.4.6.24', refT='Jerarquía de controles'),

 dict(nivel='advanced', tema='Reserva de la historia clínica ocupacional',
  ctx='Un jefe le pide a usted que le informe qué dijo el examen médico ocupacional de un servidor de su equipo, porque «necesita saber si puede asignarle una tarea pesada». Le dice que no quiere el documento, solo que le cuente lo esencial, y que es por el bien del servidor. El servidor no sabe de esta conversación. Usted tiene acceso al archivo donde reposan los certificados de aptitud y sabe que existe un canal previsto para este tipo de necesidad.',
  q='¿Cuál es la actuación correcta?',
  ops=['Contarle lo esencial sin entregar el documento, porque el jefe tiene una necesidad legítima de organización del trabajo y una explicación verbal no constituye entrega de información reservada.',
       'Explicarle que la historia clínica ocupacional es reservada y pertenece al trabajador, que lo que la entidad recibe es el certificado de aptitud con recomendaciones, y orientarlo sobre cómo obtenerlo.',
       'Entregarle copia del examen porque es el jefe inmediato del servidor y requiere la información para una decisión de asignación de tareas que hace parte de sus funciones de dirección.',
       'Negarse sin más y no dar ninguna orientación, porque cualquier información relacionada con la salud del servidor está prohibida para el empleador y no existe canal alguno para obtenerla.'],
  correcta=1,
  expl=['Incorrecto: contar «lo esencial» de un dato de salud es revelarlo.',
        'Correcto: la historia clínica es reservada; lo que el empleador recibe es el certificado de aptitud con recomendaciones.',
        'Incorrecto: entregar el examen desconoce la reserva.',
        'Incorrecto: negarse sin orientar deja al jefe sin la información que sí puede tener.'],
  ref='Resolución 2346 de 2007 y Ley 1581 de 2012', refT='Reserva de la historia clínica ocupacional'),

 dict(nivel='basic', tema='Debido proceso administrativo',
  ctx='Un servidor de carrera va a ser retirado por una causal legal. El jefe de su dependencia le pide a usted que proyecte el acto «sin entrar en detalles, para no darle argumentos» y que se le comunique el mismo día en que deba dejar el cargo, sin dar tiempo a nada. Le dice que entre menos sepa, menos problemas habrá para la entidad, y que la causal es tan clara que no necesita explicación adicional. El servidor lleva once años en la entidad.',
  q='¿Qué debe precisar?',
  ops=['Que el debido proceso aplica a toda actuación administrativa: el acto debe motivarse, notificarse en debida forma e indicar los recursos, y el servidor debe poder ejercer su defensa.',
       'Que el debido proceso solo rige en las actuaciones judiciales y disciplinarias, de modo que un acto de retiro puede adoptarse y comunicarse sin esas formalidades cuando hay causal legal.',
       'Que basta con que el acto invoque la causal legal, sin desarrollar los hechos, porque la sola mención de la norma aplicada satisface la exigencia constitucional de motivación del acto.',
       'Que el servidor podrá controvertir la decisión ante la jurisdicción, de modo que las garantías en sede administrativa pueden simplificarse para no dilatar una decisión ya adoptada.'],
  correcta=0,
  expl=['Correcto: el art. 29 aplica a toda clase de actuaciones judiciales y administrativas.',
        'Incorrecto: el texto constitucional es expreso en incluir las administrativas.',
        'Incorrecto: invocar la causal sin desarrollar los hechos no es motivar.',
        'Incorrecto: la vía judicial posterior no autoriza a recortar garantías en sede administrativa.'],
  ref='Constitución Política, art. 29', refT='Debido proceso administrativo'),

 dict(nivel='intermediate', tema='Integridad del expediente',
  ctx='Al conformar una historia laboral, usted encuentra que entre el folio 47 y el 49 no está el 48, que el índice menciona un documento que no aparece y que hay tres hojas sueltas sin foliar al final de la carpeta. Un compañero propone refoliar todo desde el principio para que quede continuo y archivar las sueltas donde «parezca que van». El expediente debe remitirse al archivo central el viernes y soporta dos certificaciones ya expedidas.',
  q='¿Cuál es la actuación correcta?',
  ops=['Dejar constancia escrita y detallada de cada hallazgo, no alterar la foliación existente ni ubicar documentos por criterio propio, e informarlo por el canal para que el competente disponga.',
       'Refoliar la carpeta completa desde el folio uno e incorporar las hojas sueltas en el orden cronológico que corresponda, de modo que el expediente quede íntegro antes de su remisión.',
       'Remitir el expediente como está y advertir verbalmente al archivo central, porque la responsabilidad de la conformación recae en quien integró la carpeta y no en quien la remite ahora.',
       'Retirar las hojas sueltas y el índice inconsistente y remitir solo los folios numerados, de modo que el expediente que llegue al archivo central no contenga documentos irregulares.'],
  correcta=0,
  expl=['Correcto: la trazabilidad es lo que hace confiable el expediente; se documenta y se informa, sin alterar nada.',
        'Incorrecto: refoliar borra la huella del problema.',
        'Incorrecto: advertir verbalmente no deja registro.',
        'Incorrecto: retirar documentos es una depuración que no le corresponde.'],
  ref='Ley 594 de 2000 y Acuerdo 02 de 2014 del AGN', refT='Integridad y foliación del expediente'),

 dict(nivel='advanced', tema='Corrección de errores formales',
  ctx='Un acto administrativo de personal quedó con un error en la liquidación de un valor: se sumó mal una cifra, aunque todos los conceptos y la decisión son correctos. El acto ya fue notificado y archivado en la historia laboral del servidor con esa cifra. Un compañero propone revocarlo y expedir uno nuevo; otro, dejarlo así y ajustar la diferencia en la nómina sin tocar el documento. El interesado todavía no ha advertido el error.',
  q='¿Cuál es la actuación correcta?',
  ops=['Proyectar la corrección del error aritmético, que procede en cualquier tiempo, de oficio o a petición de parte, siempre que no se altere el sentido material de la decisión adoptada.',
       'Proyectar la revocatoria del acto y expedir uno nuevo con la cifra correcta, porque cualquier error numérico afecta la validez del acto y exige retirarlo del ordenamiento jurídico.',
       'Ajustar la diferencia directamente en la nómina y dejar una anotación interna, porque lo relevante es que el servidor reciba el valor correcto y el documento no necesita modificarse.',
       'Esperar a que el interesado advierta el error y lo reclame, porque corregir de oficio un acto ya notificado podría interpretarse como una modificación unilateral en su perjuicio.'],
  correcta=0,
  expl=['Correcto: los errores aritméticos y de transcripción se corrigen en cualquier tiempo, sin alterar el sentido material de la decisión.',
        'Incorrecto: revocar por un error de suma es desproporcionado.',
        'Incorrecto: dejaría el acto y el pago diciendo cosas distintas.',
        'Incorrecto: la corrección procede de oficio.'],
  ref='Ley 1437 de 2011, art. 45', refT='Corrección de errores formales'),

 dict(nivel='intermediate', tema='Peticiones reiteradas',
  ctx='Una servidora presenta una petición y, a la semana, presenta otra idéntica, y luego una tercera sobre el mismo asunto. La primera ya fue respondida de fondo, notificada y archivada, con constancia de su fecha. Un compañero propone no responder las dos siguientes «porque ya se le contestó» y otro, volver a estudiar el asunto desde cero en cada una. Al comparar los tres escritos, usted confirma que el tercero añade un hecho nuevo que no figuraba en los anteriores.',
  q='¿Cuál es la actuación correcta?',
  ops=['No responder las peticiones posteriores, porque el asunto ya fue resuelto de fondo y responder lo mismo una y otra vez constituye un desgaste injustificado para la administración.',
       'Estudiar el asunto de nuevo en cada petición, porque cada escrito es una petición autónoma que genera para la entidad el deber de pronunciarse de fondo sobre todo lo solicitado.',
       'Responder remitiéndose a la respuesta ya dada, indicando su fecha y cómo obtenerla, y resolver además el hecho nuevo que el tercer escrito introduce y que no fue resuelto antes.',
       'Responder la segunda petición y archivar la tercera, porque a partir de la segunda reiteración puede entenderse que la peticionaria ejerce abusivamente su derecho de petición.'],
  correcta=2,
  expl=['Incorrecto: el silencio no es opción, por reiterada que sea la petición.',
        'Incorrecto: volver a estudiar todo sin hechos nuevos es un desgaste innecesario.',
        'Correcto: se remite a la respuesta ya dada y se resuelve lo nuevo; la verificación es lo que no puede omitirse.',
        'Incorrecto: no cabe declarar abusivo el ejercicio de un derecho fundamental por la reiteración.'],
  ref='Ley 1437 de 2011, art. 19', refT='Peticiones reiteradas'),

 dict(nivel='basic', tema='Publicación de actos generales',
  ctx='Un acto de carácter general que afecta a todos los servidores de una sede va a adoptarse: modifica el horario de atención y debe empezar a regir el primer día del mes siguiente, de modo que el público también debe conocerlo antes. Un compañero propone notificarlo personalmente a cada servidor «para que nadie alegue desconocimiento», lo que tomaría semanas. Otro propone enviarlo por correo masivo y no hacer ningún otro trámite.',
  q='¿Cuál es la forma correcta de darlo a conocer?',
  ops=['Notificarlo personalmente a cada servidor, porque es la forma que ofrece mayor certeza sobre el conocimiento efectivo de la decisión por parte de todos sus destinatarios directos.',
       'Publicarlo, que es la forma de dar a conocer los actos de carácter general, en el medio oficialmente previsto, y comunicarlo además por los canales internos de la entidad.',
       'Enviarlo por correo electrónico masivo a todos los servidores de la sede, porque ese medio garantiza la difusión simultánea y deja constancia automática del envío a cada destinatario.',
       'Fijarlo en la cartelera de la sede durante diez días hábiles, transcurridos los cuales se entiende notificado personalmente a cada uno de los servidores que allí laboran.'],
  correcta=1,
  expl=['Incorrecto: la notificación personal es propia de los actos de contenido particular.',
        'Correcto: los actos generales se dan a conocer por publicación; la difusión interna es complementaria.',
        'Incorrecto: el correo masivo es difusión, no publicación.',
        'Incorrecto: la cartelera tampoco sustituye la publicación.'],
  ref='Ley 1437 de 2011, art. 65', refT='Publicidad de los actos generales'),

 dict(nivel='advanced', tema='Recurso y ejecución del acto',
  ctx='Un servidor interpone recurso de reposición contra un acto que le negó una prima. Mientras el recurso se resuelve, el jefe de su dependencia pide a la División que ejecute el acto, es decir, que no incluya el factor en la nómina del mes y cierre el asunto. Un compañero le dice a usted que el recurso «no detiene nada» porque el acto ya fue notificado. El cierre de la nómina es el viernes y el recurso apenas entró a estudio del competente.',
  q='¿Qué debe precisar?',
  ops=['Que el recurso no afecta la ejecución del acto, porque una vez notificada la decisión produce todos sus efectos hasta que sea revocada o anulada por la autoridad que resulte competente.',
       'Que el recurso suspende la ejecución de manera indefinida y que el acto no podrá ejecutarse nunca si el recurrente no manifiesta expresamente su conformidad con lo que se decida.',
       'Que la interposición del recurso impide que el acto quede en firme y, por tanto, que se ejecute: debe esperarse a que se resuelva, e informar a la dependencia el estado real del trámite.',
       'Que el recurso solo suspende la ejecución si el recurrente lo pide expresamente y presta una caución que garantice los perjuicios que la demora pueda causar a la entidad empleadora.'],
  correcta=2,
  expl=['Incorrecto: confunde notificación con firmeza.',
        'Incorrecto: la suspensión dura hasta que el recurso se resuelva, no es indefinida.',
        'Correcto: un acto recurrido no está en firme y lo que no está en firme no se ejecuta.',
        'Incorrecto: no existe caución alguna como condición para ese efecto.'],
  ref='Ley 1437 de 2011, arts. 79 y 87', refT='Efectos de la interposición del recurso'),

 dict(nivel='intermediate', tema='Igualdad y aplicación uniforme',
  ctx='Dos servidoras en la misma situación de hecho reciben respuestas distintas a la misma solicitud, con pocas semanas de diferencia y sin que haya cambiado la norma aplicable. La segunda lo advierte, compara los dos documentos y reclama por escrito. Un compañero le dice a usted que «cada caso es distinto» y que no hay nada que explicar ni que revisar. El jefe pregunta cómo debe manejarse el asunto, porque hay otros expedientes del mismo tipo pendientes.',
  q='¿Cuál es la lectura correcta?',
  ops=['No hay problema alguno: la administración decide caso por caso y no queda vinculada por sus decisiones anteriores, de modo que respuestas distintas no requieren justificación especial.',
       'Debe responderse a la segunda servidora invocando la decisión más reciente, porque es la que refleja el criterio actual de la entidad y deja sin efecto la posición adoptada antes.',
       'Debe revocarse la primera respuesta para que ambas queden iguales, porque la igualdad exige que, ante dos decisiones distintas, prevalezca siempre la menos favorable al interesado.',
       'El derecho a la igualdad y el principio de aplicación uniforme exigen resolver igual los casos iguales: si el criterio cambia, debe motivarse el cambio, y el asunto debe revisarse.'],
  correcta=3,
  expl=['Incorrecto: decir que «cada caso es distinto» sin mostrar en qué lo es es lo que la igualdad prohíbe.',
        'Incorrecto: imponer la decisión reciente sin justificar el cambio no resuelve la inconsistencia.',
        'Incorrecto: no hay razón para que prevalezca la menos favorable.',
        'Correcto: los casos iguales se resuelven igual y el cambio de criterio debe motivarse.'],
  ref='Constitución Política, art. 13; Ley 1437 de 2011, art. 10', refT='Aplicación uniforme de las normas'),

 dict(nivel='advanced', tema='Anotaciones en la historia laboral',
  ctx='Un jefe de dependencia le pide a usted que incluya en la hoja de vida de un servidor una anotación sobre un llamado de atención verbal que le hizo la semana pasada por llegar tarde dos veces. Le dice que quiere que «quede el antecedente» por si la conducta se repite, y que lo redacte usted mismo con sus palabras. No hay actuación disciplinaria, ni acto administrativo, ni decisión de autoridad competente alguna sobre el asunto.',
  q='¿Cuál es la actuación correcta?',
  ops=['Incluir la anotación con la fecha del llamado de atención, porque el jefe inmediato conoce la conducta del servidor y tiene interés legítimo en que quede registrada en su hoja de vida.',
       'Incluir la anotación pero en una carpeta interna de la dependencia y no en la historia laboral oficial, de modo que el jefe conserve el registro sin afectar el expediente formal.',
       'Explicarle que en la historia laboral solo se incorporan los documentos y actos que la norma prevé, y que una anotación de sanción requiere decisión en firme de autoridad competente.',
       'Negarse e informar el hecho a la oficina de control interno disciplinario, porque la solicitud del jefe podría constituir en sí misma una falta disciplinaria que debería investigarse.'],
  correcta=2,
  expl=['Incorrecto: crearía un antecedente sin fundamento.',
        'Incorrecto: un registro oculto sobre una persona, fuera de todo control, es peor.',
        'Correcto: solo se incorpora lo que la norma prevé; una anotación de sanción exige decisión en firme del competente.',
        'Incorrecto: lo primero es explicarle por qué no procede, no denunciarlo de inmediato.'],
  ref='Decreto 1083 de 2015, art. 2.2.17.6; Ley 1952 de 2019', refT='Contenido de la historia laboral'),

 dict(nivel='intermediate', tema='Contingencia y cumplimiento de parámetros',
  ctx='La Oficina de Sistemas le informa que el aplicativo de nómina presentará una falla durante dos días, justo en la semana del cierre. Su jefe está de vacaciones y el calendario de pago no se puede mover. Un compañero propone liquidar esos dos días en una hoja de cálculo paralela «y después subirlo todo», y otro propone avisar al final, cuando se sepa si alcanzó a afectar el cierre. Son más de mil servidores los que dependen de ese pago.',
  q='¿Cuál es la actuación correcta?',
  ops=['Informar de inmediato la contingencia por el canal, con su impacto estimado en el cierre, documentar lo que se avance y actuar conforme a lo que se disponga, dejando constancia del procedimiento usado.',
       'Liquidar en una hoja de cálculo paralela y cargar los datos cuando el aplicativo se restablezca, porque lo importante es que el calendario de pago se cumpla sin afectar a los servidores.',
       'Esperar a que el jefe regrese de vacaciones para que él decida, porque es una contingencia que excede la competencia de quien opera la nómina y nadie más puede autorizar un cambio.',
       'Avisar al final de la semana, una vez se confirme si la falla alcanzó a afectar el cierre, para no generar una alarma que podría resultar innecesaria si el aplicativo se restablece a tiempo.'],
  correcta=0,
  expl=['Correcto: la contingencia se informa cuando se conoce, no cuando se confirma el daño; así alguien con competencia decide a tiempo.',
        'Incorrecto: una liquidación paralela rompe la trazabilidad y los controles del sistema.',
        'Incorrecto: esperar al regreso del jefe desatiende una urgencia que tiene otros canales.',
        'Incorrecto: avisar al final convierte una contingencia manejable en un incumplimiento consumado.'],
  ref='Decreto 1499 de 2017 (MIPG) y procedimientos internos', refT='Cumplimiento de parámetros ante contingencias'),
]
